// ---------------------------------------------------------------------------
// Basic types
// ---------------------------------------------------------------------------

export type Json = null | boolean | number | string | Json[] | { [key: string]: Json };

export interface Issue {
  path: string;
  code: string;
  message: string;
}

export interface Page<T> {
  items: T[];
  total: string;
  page: number;
  size: number;
}

export type Format = 'email' | 'uri' | 'hostname' | 'ipv4' | 'ipv6';

interface Bounds {
  min?: number;
  max?: number;
  minLen?: number;
  maxLen?: number;
  pattern?: string;
  format?: Format;
  // #if rules
  /** The check function of a declaration with invariants (see `checkValue`). */
  rules?: RuleCheck;
  // #endif
  // #if derived
  /** The compute function of a declaration with derived fields (see `deriveNode`). */
  derive?: DeriveFn;
  // #endif
  // #if visibility
  /** The generated function of a declaration with `@visible` fields (see `showNode`). */
  show?: ShowFn;
  // #endif
  // #if tenancy
  /** The `@tenant` field of a tenant-scoped declaration (see `tenantNode`). */
  tn?: TenantField;
  // #endif
}

export interface FieldSchema {
  /** Source name (the property name in TypeScript). */
  n: string;
  /** Wire name, only when it differs from `n`. */
  w?: string;
  t: Schema;
  /** Optional. */
  o?: boolean;
  /** Default value, applied when the field is absent. */
  d?: Json;
  /** Read-only: ignored in request bodies. */
  ro?: boolean;
  // #if derived
  /** Derived (`spec/rules.md` section 17.2): computed, never supplied, never required of a value. */
  dv?: boolean;
  // #endif
  // #if tenant_fields
  /** Set by the server (`@tenant`): a request may lack it, and one that carries it is kept as received. */
  st?: boolean;
  // #endif
  // #if audit
  /** `@pii` or `@secret`: the value is left out of an audit event. */
  pii?: boolean;
  // #endif
}

export type Schema = Bounds &
  (
    | {
        k:
          | 'string'
          | 'int'
          | 'long'
          | 'float'
          | 'decimal'
          | 'bool'
          | 'date'
          | 'datetime'
          | 'time'
          | 'uuid'
          | 'bytes'
          | 'json';
      }
    | { k: 'enum'; values: readonly string[] }
    | { k: 'list' | 'map' | 'page'; of: Schema }
    | { k: 'object'; fields: readonly FieldSchema[]; sig?: string }
    | { k: 'union'; d: string; arms: Readonly<Record<string, Schema>>; sig?: string }
    | { k: 'ref'; to: () => Schema }
  );

function isObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function resolve(s: Schema): Schema {
  let cur = s;
  while (cur.k === 'ref') cur = cur.to();
  return cur;
}

// ---------------------------------------------------------------------------
// Canonical JSON (RFC 8785)
// ---------------------------------------------------------------------------

export function canonical(value: unknown): string {
  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
    return JSON.stringify(value);
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError('canonical: non-finite number');
    return JSON.stringify(value);
  }
  if (Array.isArray(value)) {
    return `[${value.map((x) => canonical(x === undefined ? null : x)).join(',')}]`;
  }
  if (typeof value === 'object') {
    const o = value as Record<string, unknown>;
    const keys = Object.keys(o)
      .filter((k) => o[k] !== undefined)
      .sort();
    return `{${keys.map((k) => `${JSON.stringify(k)}:${canonical(o[k])}`).join(',')}}`;
  }
  throw new TypeError(`canonical: unsupported value of type ${typeof value}`);
}

