// Errors
// ---------------------------------------------------------------------------

export interface ErrorInit {
  status?: number;
  op?: string | null;
  // #if rules
  violations?: Violation[];
  local?: boolean;
  // #endif
}

export class VeldError<D = unknown> extends Error {
  readonly veld = 1 as const;
  readonly sig: string;
  readonly title: string;
  readonly data: D;
  status: number;
  /** Operation signature, or `null` until the error is raised from an endpoint. */
  op: string | null;
  // #if rules
  /** The rule violations of a `ValidationError`; empty when there are none. */
  violations: Violation[];
  /** True when the client raised this error itself, before sending anything. */
  local: boolean;
  // #endif

  constructor(sig: string, title: string, data: D, init: ErrorInit = {}, defaultStatus = 500) {
    super(title);
    this.name = title;
    this.sig = sig;
    this.title = title;
    this.data = data;
    this.status = init.status ?? defaultStatus;
    this.op = init.op ?? null;
    // #if rules
    this.violations = init.violations ?? [];
    this.local = init.local ?? false;
    // #endif
  }
}

/** A non-2xx response that is not one of the endpoint's declared errors. */
export class VeldHttpError extends Error {
  readonly status: number;
  readonly body: unknown;

  constructor(status: number, body: unknown) {
    super(`HTTP ${status}`);
    this.name = 'VeldHttpError';
    this.status = status;
    this.body = body;
  }
}

/** A network failure, or a response body that cannot be understood. */
export class VeldTransportError extends Error {
  constructor(message: string, cause?: unknown) {
    super(message);
    // `new Error(message, { cause })` needs ES2022; this is the same non-enumerable own property.
    if (cause !== undefined) Object.defineProperty(this, 'cause', { value: cause, writable: true, configurable: true });
    this.name = 'VeldTransportError';
  }
}

export function isVeldError(e: unknown): e is VeldError {
  return isObject(e) && e['veld'] === 1 && typeof e['sig'] === 'string';
}

function packageOf(sig: string): string {
  return sig.slice(sig.indexOf(':') + 1, sig.lastIndexOf('/'));
}

/** `veld:pkg/Service.endpoint@hash` -> `pkg/Service`. */
export function serviceOfOp(op: string): string {
  return op.slice(op.indexOf(':') + 1, op.lastIndexOf('.'));
}

/**
 * Whether `e` is the declaration `sig`. When the error was raised from an
 * endpoint (`op` is set) it must also come from the declaring service: for a
 * prelude error any service matches unless `service` (`pkg/Service`) is given.
 */
export function matchesError(e: unknown, sig: string, service?: string): boolean {
  if (!isVeldError(e) || e.sig !== sig) return false;
  if (e.op === null) return true;
  if (service !== undefined) return serviceOfOp(e.op) === service;
  const pkg = packageOf(sig);
  return pkg === 'veld' || packageOf(e.op) === pkg;
}

/**
 * Canonical bytes of an error's data. Schema defaults are applied first, so an
 * absent defaulted field equals the same field written out (spec/ir.md 5.3).
 * The schema is the declaring class's static `schema`; an error of an unknown
 * type falls back to its data as written.
 */
export function canonicalError(e: VeldError): string {
  const schema = (e.constructor as { schema?: Schema }).schema;
  return schema === undefined ? canonical(e.data) : canonicalOf(schema, e.data);
}

/**
 * Declaration identity of a value (spec/ir.md 5.4). Every value the generated code produces
 * (client decode, server request binding, `Model.of`) carries its declaration `sig` and schema
 * under these non-enumerable symbols: JSON.stringify, `Object.keys` and spreads do not see them.
 * `Symbol.for` makes them the same symbols in every separately generated copy of this runtime.
 */
export const SIG: unique symbol = Symbol.for('veld.sig') as never;
const SCHEMA: unique symbol = Symbol.for('veld.schema') as never;

/** Stamps `value` (in place) with its declaration identity and returns it. Primitives are returned as is. */
export function stamp<T>(value: T, sig: string, schema: Schema): T {
  if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
    Object.defineProperties(value, {
      [SIG]: { value: sig, configurable: true, writable: true },
      [SCHEMA]: { value: schema, configurable: true, writable: true },
    });
  }
  return value;
}

/** The declaration signature a value carries, or `undefined`. */
export function sigOf(value: unknown): string | undefined {
  if (isVeldError(value)) return value.sig;
  if (typeof value !== 'object' || value === null) return undefined;
  const s = (value as Record<symbol, unknown>)[SIG];
  return typeof s === 'string' ? s : undefined;
}

/**
 * Equality by identity (spec/ir.md 5.4): the same declaration signature (for errors also the same
 * operation) and the same canonical bytes. It works across separately generated copies of the
 * runtime, because it reads only the signature symbol, `op` and the canonical data.
 *
 * Both operands must carry a declaration identity (decoded by a client, bound by a server, built
 * with `Model.of`, or an error). `same` never guesses: an operand without identity (a plain object
 * literal, a primitive such as an enum value, a `Page`) throws a `TypeError` that names the fix,
 * because answering `false` would silently hide a bug and answering by data alone is the bug
 * this rule exists to prevent. Arrays are compared element by element. For plain objects use the
 * companion, `Model.same(a, b)`, where the declaration is implied.
 */
export function same(a: unknown, b: unknown): boolean {
  if (isVeldError(a) || isVeldError(b)) {
    if (!isVeldError(a) || !isVeldError(b)) return false;
    return a.sig === b.sig && a.op === b.op && canonicalError(a) === canonicalError(b);
  }
  if (Array.isArray(a) || Array.isArray(b)) {
    return Array.isArray(a) && Array.isArray(b) && a.length === b.length && a.every((x, i) => same(x, b[i]));
  }
  const sa = sigOf(a);
  const sb = sigOf(b);
  if (sa === undefined || sb === undefined) {
    throw new TypeError(
      `same(): ${sa === undefined ? 'the first' : 'the second'} operand carries no declaration identity ` +
        '(it is a plain object or a primitive). Compare with the companion, `Model.same(a, b)`, or build the ' +
        'value with `Model.of(...)`.',
    );
  }
  if (sa !== sb) return false;
  const sch = (a as Record<symbol, unknown>)[SCHEMA] as Schema | undefined;
  const other = (b as Record<symbol, unknown>)[SCHEMA] as Schema | undefined;
  const ca = sch === undefined ? canonical(a) : canonicalOf(sch, a);
  const cb = other === undefined ? canonical(b) : canonicalOf(other, b);
  return ca === cb;
}

