// #if version

// ---------------------------------------------------------------------------
// Optimistic concurrency: If-Match and ETag (spec/rules.md sections 11.7 and 11.9)
// ---------------------------------------------------------------------------

const IF_MATCH_MESSAGE = 'must be * or one strong entity tag holding a version, such as "3"';

/** The largest `long`. */
const MAX_LONG = 9223372036854775807n;

/**
 * Reads an `If-Match` value: `*`, or the digits of one strong entity tag that holds a version
 * (`"0"`, or a digit from 1 to 9 and more digits, within `long`). `null` for anything else: a weak
 * tag, a list, a sign, a leading zero, spaces.
 */
function parseIfMatch(text: string): '*' | { digits: string } | null {
  if (text === '*') return '*';
  const m = /^"(0|[1-9][0-9]*)"$/.exec(text);
  const digits = m?.[1];
  return digits !== undefined && BigInt(digits) <= MAX_LONG ? { digits } : null;
}

/** The header a client writes for `ifMatch`: `*`, or the version as a strong entity tag. */
function ifMatchText(v: unknown): string {
  return v === '*' ? '*' : `"${scalarString(v)}"`;
}

/** The step 5 issue of a malformed `If-Match` on an endpoint with a guard. No other endpoint reads the header. */
function ifMatchIssues(ep: EndpointSpec, headers: Headers): Issue[] {
  const sent = firstHeader(headers, 'if-match');
  if (ep.ifMatch !== true || sent === undefined || parseIfMatch(sent) !== null) return [];
  return [{ path: 'header.If-Match', code: 'type', message: IF_MATCH_MESSAGE }];
}

/** `ETag: "<version>"` on a success whose type is the model that has the version field. */
function withEtag(ep: EndpointSpec, res: VeldResponse, result: unknown): VeldResponse {
  if (ep.etag === undefined || !isObject(result)) return res;
  const held = result[ep.etag];
  if (typeof held !== 'number' && typeof held !== 'string') return res;
  return { ...res, headers: { ...res.headers, etag: `"${held}"` } };
}
// #endif
// #if version_guard

/** The version guard of an endpoint (`fact room: Room`, `Room` has a `@version` field). */
export interface VersionStep {
  /** The rule's id. */
  id: string;
  /** The fact that is compared. */
  fact: string;
  /** The version field of the fact's model, by its source name. */
  field: string;
  /** The declared error that answers a stale tag: `PreconditionFailed`. */
  otherwise: { sig: string };
}

export interface EndpointRuleSet {
  version?: VersionStep;
}

/**
 * Step 6, after the policies and before the transition guard: `412 PreconditionFailed` when the
 * caller sent a tag that is not the version the fact holds. `*`, no header and an absent fact
 * pass. A tag that was compared is handed to the handler as `version`. This runs even when
 * request validation is off. A malformed `If-Match` was refused at step 5.
 *
 * The check is a guard, not an atomic guarantee: a second request can change the row after it.
 * The handler writes conditionally and answers `PreconditionFailed` itself when the row has moved.
 */
function checkVersion(
  ep: ServerEndpoint,
  rules: EndpointRuleSet,
  ctx: RequestContext,
  std: StdSigs,
  hooks: HandlerHooks,
  at: { f: Record<string, unknown>; started: number },
): VeldResponse | null {
  const step = rules.version;
  const sent = step === undefined ? null : parseIfMatch(firstHeader(ctx.headers, 'if-match') ?? '');
  if (step === undefined || sent === null || sent === '*') return null;
  const fact = at.f[step.fact];
  if (!isObject(fact)) return null;
  const held = fact[step.field];
  const actual = String(held);
  if (actual === sent.digits) {
    at.f['version'] = typeof held === 'number' ? Number(sent.digits) : sent.digits;
    return null;
  }
  const violation: Violation = { rule: step.id, path: 'request', fields: [], message: 'violates rule version' };
  const data = { expected: sent.digits, actual };
  return refusal(ep, ctx, std, hooks, { sig: step.otherwise.sig, data, violation, started: at.started });
}
// #endif
// #if idempotency_only

/**
 * A response the endpoint's `call` may return in place of a result, sent as it is. Without endpoint
 * rules it is the test handler's way to stop a dry run.
 */
export class EarlyResponse {
  readonly response: VeldResponse;

  constructor(response: VeldResponse) {
    this.response = response;
  }
}
// #endif
// #if idempotency

// ---------------------------------------------------------------------------
// Idempotent endpoints (spec/rules.md sections 11.8, 11.9 and 11.12)
// ---------------------------------------------------------------------------

/** `@idempotent` on an endpoint. */
export interface IdempotencySpec {
  /** The request header that carries the key. */
  header: string;
  /** A request without the header is `422 ValidationError`. */
  required: boolean;
  /** The scope of a key includes the caller (the endpoint has auth). */
  caller: boolean;
}

/** What the store keeps of an answer: enough to send it again. */
export interface StoredAnswer {
  status: number;
  /** The bytes that were sent, `null` for an answer without a body. */
  body: string | null;
  contentType?: string;
  etag?: string;
  location?: string;
}

/** What the store says about a key. */
export type IdempotencyBegin =
  | { state: 'started' }
  | { state: 'replay'; answer: StoredAnswer }
  | { state: 'running' }
  | { state: 'other' };

/**
 * Where idempotency keys live. Implement it over a shared database or cache; how long an entry is
 * kept is the store's business.
 *
 * `begin` is atomic: of two concurrent calls for a key the store does not know, exactly one gets
 * `started`. A key held with another fingerprint is `other`, whether its request is running or its
 * answer is stored. `scope` is one opaque text: the operation signature and, for an endpoint with
 * auth, a line feed and the caller.
 */
export interface IdempotencyStore {
  begin(scope: string, key: string, fingerprint: string): Promise<IdempotencyBegin>;
  /** Stores the answer of a request `begin` started. */
  complete(scope: string, key: string, answer: StoredAnswer): Promise<void>;
  /** Removes the entry of a request `begin` started: its answer is not stored. */
  release(scope: string, key: string): Promise<void>;
}

/** The hooks of a server with an `@idempotent` endpoint. */
export interface IdempotencyHooks {
  store: IdempotencyStore;
  /** Who the caller is, as text, for the scope of a key. Needed by an endpoint with auth. */
  caller?: (principal: never, ctx: RequestContext) => string | Promise<string>;
}

/** An `IdempotencyStore` in memory. It keeps every entry for as long as it lives: for tests. */
export class MemoryIdempotencyStore implements IdempotencyStore {
  private readonly entries = new Map<string, { fingerprint: string; answer?: StoredAnswer }>();

  begin(scope: string, key: string, fingerprint: string): Promise<IdempotencyBegin> {
    const id = JSON.stringify([scope, key]);
    const held = this.entries.get(id);
    if (held === undefined) {
      this.entries.set(id, { fingerprint });
      return Promise.resolve({ state: 'started' });
    }
    if (held.fingerprint !== fingerprint) return Promise.resolve({ state: 'other' });
    return Promise.resolve(held.answer === undefined ? { state: 'running' } : { state: 'replay', answer: held.answer });
  }

  complete(scope: string, key: string, answer: StoredAnswer): Promise<void> {
    const held = this.entries.get(JSON.stringify([scope, key]));
    if (held !== undefined) held.answer = answer;
    return Promise.resolve();
  }

  release(scope: string, key: string): Promise<void> {
    this.entries.delete(JSON.stringify([scope, key]));
    return Promise.resolve();
  }
}

const SHA256_K: readonly number[] = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

function rotr(x: number, n: number): number {
  return (x >>> n) | (x << (32 - n));
}

function wordAt(a: readonly number[], i: number): number {
  return a[i] ?? 0;
}

/** The message schedule of one 64-byte block. */
function schedule(m: readonly number[], at: number): number[] {
  const w: number[] = [];
  for (let t = 0; t < 64; t++) {
    if (t < 16) {
      const i = at + 4 * t;
      w.push((wordAt(m, i) << 24) | (wordAt(m, i + 1) << 16) | (wordAt(m, i + 2) << 8) | wordAt(m, i + 3));
    } else {
      const a = wordAt(w, t - 15);
      const b = wordAt(w, t - 2);
      const s0 = rotr(a, 7) ^ rotr(a, 18) ^ (a >>> 3);
      const s1 = rotr(b, 17) ^ rotr(b, 19) ^ (b >>> 10);
      w.push((wordAt(w, t - 16) + s0 + wordAt(w, t - 7) + s1) | 0);
    }
  }
  return w;
}

/** SHA-256 of `bytes` as 64 lowercase hex characters. Plain code, so it runs wherever the runtime does. */
function sha256Hex(bytes: readonly number[]): string {
  const h = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const m = [...bytes, 0x80];
  while (m.length % 64 !== 56) m.push(0);
  const bits = bytes.length * 8;
  for (const word of [Math.floor(bits / 0x100000000), bits >>> 0]) {
    for (let s = 24; s >= 0; s -= 8) m.push((word >>> s) & 255);
  }
  for (let at = 0; at < m.length; at += 64) {
    const w = schedule(m, at);
    let [a, b, c, d, e, f, g, k] = h.map((x) => x | 0) as [number, number, number, number, number, number, number, number];
    for (let t = 0; t < 64; t++) {
      const t1 = (k + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + wordAt(SHA256_K, t) + wordAt(w, t)) | 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      [k, g, f, e, d, c, b, a] = [g, f, e, (d + t1) | 0, c, b, a, (t1 + t2) | 0];
    }
    [a, b, c, d, e, f, g, k].forEach((x, i) => {
      h[i] = (wordAt(h, i) + x) | 0;
    });
  }
  return h.map((x) => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

/** A datetime in UTC with `.mmm` only when it is not zero: the form of the reference evaluator (`.250Z`, where `canonicalOf` has `.25Z`). */
function referenceDatetime(v: string): string {
  const ms = Date.parse(v);
  return Number.isNaN(ms) ? v : new Date(ms).toISOString().replace('.000Z', 'Z');
}

/** The wire form of a value in the normal form of the reference evaluator: a uuid in lower case, a datetime as above, a long as the decimal text of its value (`007` is `7`, `-0` is `0`). */
function normalForm(s: Schema, v: unknown): unknown {
  const t = resolve(s);
  switch (t.k) {
    case 'uuid':
      return typeof v === 'string' ? v.toLowerCase() : v;
    case 'datetime':
      return typeof v === 'string' && RE_DATETIME.test(v) ? referenceDatetime(v) : v;
    case 'long':
      return typeof v === 'string' && RE_LONG.test(v) ? BigInt(v).toString() : v;
    case 'list':
      return Array.isArray(v) ? v.map((x) => normalForm(t.of, x)) : v;
    case 'map': {
      if (!isObject(v)) return v;
      const out: Record<string, unknown> = {};
      for (const k of Object.keys(v)) out[k] = normalForm(t.of, v[k]);
      return out;
    }
    case 'page':
      return isObject(v) ? { ...v, items: normalForm({ k: 'list', of: t.of }, v['items']) } : v;
    case 'object': {
      if (!isObject(v)) return v;
      const out: Record<string, unknown> = { ...v };
      for (const f of t.fields) {
        const key = f.w ?? f.n;
        // #endif
        // #if idempotency_tenant
        if (f.st === true) {
          delete out[key];
          continue;
        }
        // #endif
        // #if idempotency
        if (out[key] !== undefined) out[key] = normalForm(f.t, out[key]);
      }
      return out;
    }
    case 'union': {
      const label = isObject(v) ? v[t.d] : undefined;
      const arm = typeof label === 'string' && Object.prototype.hasOwnProperty.call(t.arms, label) ? t.arms[label] : undefined;
      return arm === undefined ? v : normalForm(arm, v);
    }
    default:
      return v;
  }
}

/**
 * The fingerprint of a request: the first 16 hex characters of the SHA-256 of the RFC 8785 JSON of
 * the bound parameters in wire form, keyed by parameter name (defaults applied, absent optionals
 * left out, a uuid in lower case, a datetime in UTC). The header of the key is not a parameter.
 */
function fingerprintOf(ep: EndpointSpec, bound: Bound): string {
  const wire: Record<string, unknown> = {};
  for (const p of ep.params) {
    const v = p.s ? undefined : bound.value[p.name];
    if (v !== undefined) wire[p.name] = normalForm(p.t, toWire(p.t, v));
  }
  return sha256Hex(utf8Bytes(canonical(wire))).slice(0, 16);
}

const KEY_PATTERN = /^[\x21-\x7e]{1,255}$/;

/** The step 5 issues of the key: malformed, or missing on a `required` endpoint. */
function keyIssues(ep: EndpointSpec, headers: Headers): Issue[] {
  const spec = ep.idempotency;
  if (spec === undefined) return [];
  const sent = firstHeader(headers, spec.header);
  const path = `header.${spec.header}`;
  if (sent === undefined) return spec.required ? [{ path, code: 'required', message: 'is required' }] : [];
  return KEY_PATTERN.test(sent) ? [] : [{ path, code: 'type', message: 'must be 1 to 255 visible ASCII characters' }];
}

/** What a request that `begin` started owes the store when it ends. */
interface Lease {
  // #endif
  // #if timeouts_idempotency
  /** Settled by the deadline: whatever the pipeline answers later is dropped. */
  closed?: boolean;
  // #endif
  // #if idempotency
  store?: IdempotencyStore;
  scope?: string;
  key?: string;
  ctx?: RequestContext;
  hooks?: HandlerHooks;
}

const OTHER_PARAMETERS = 'this idempotency key was used with other parameters';
const STILL_RUNNING = 'a request with this idempotency key is still running';

function storeFailed(lease: Lease, err: unknown): void {
  try {
    if (lease.ctx !== undefined) lease.hooks?.onError?.(err, lease.ctx);
  } catch {
    // A failing hook must not change the response.
  }
}

function replayOf(a: StoredAnswer): VeldResponse {
  const headers: Record<string, string> = {};
  if (a.contentType !== undefined) headers['content-type'] = a.contentType;
  if (a.etag !== undefined) headers['etag'] = a.etag;
  if (a.location !== undefined) headers['location'] = a.location;
  headers['veld-idempotent-replay'] = 'true';
  return { status: a.status, headers, body: a.body };
}

/**
 * After step 5 and before any fact is loaded: asks the store about the key. `null` lets the
 * request run (no key, or a new one: the lease is taken). A stored answer is sent again with
 * `Veld-Idempotent-Replay: true`; a key in use is `409 Conflict`. A store that fails is
 * `500 Internal` and the handler does not run: running without it could run a request twice.
 */
async function beginIdempotency(
  ep: ServerEndpoint,
  bound: Bound,
  ctx: RequestContext,
  std: StdSigs,
  run: { hooks: HandlerHooks; lease: Lease },
): Promise<VeldResponse | null> {
  const spec = ep.idempotency;
  const key = spec === undefined ? undefined : firstHeader(ctx.headers, spec.header);
  const idem = run.hooks.idempotency;
  if (spec === undefined || key === undefined || idem === undefined) return null;
  const lease: Lease = { store: idem.store, key, ctx, hooks: run.hooks };
  let outcome: IdempotencyBegin;
  try {
    const who = spec.caller && idem.caller !== undefined ? `\n${await idem.caller(ctx.principal as never, ctx)}` : '';
    lease.scope = `${ep.sig}${who}`;
    outcome = await idem.store.begin(lease.scope, key, fingerprintOf(ep, bound));
  } catch (err) {
    storeFailed(lease, err);
    return problem(std.internal, 'Internal', 500, ep.sig, {});
  }
  switch (outcome.state) {
    case 'started':
      // #endif
      // #if timeouts_idempotency
      if (run.lease.closed === true) {
        // The deadline passed while the store was asked: the key is not left running.
        await idem.store.release(lease.scope, key).catch((err: unknown) => storeFailed(lease, err));
        return problem(std.internal, 'Internal', 500, ep.sig, {});
      }
      // #endif
      // #if idempotency
      Object.assign(run.lease, lease);
      return null;
    case 'replay':
      return replayOf(outcome.answer);
    case 'running':
      return problem(std.conflict ?? 'about:blank', 'Conflict', 409, ep.sig, { message: STILL_RUNNING });
    case 'other':
      return problem(std.conflict ?? 'about:blank', 'Conflict', 409, ep.sig, { message: OTHER_PARAMETERS });
  }
}

/** The request is over with `res`: stores the answer below `500`, removes the entry otherwise. */
async function settle(lease: Lease, res: VeldResponse | null): Promise<VeldResponse> {
  // #endif
  // #if timeouts_idempotency
  if (lease.closed === true) {
    // The deadline settled it already: the late answer is dropped.
    if (res === null) throw new Error('the request ended without an answer');
    return res;
  }
  lease.closed = true;
  // #endif
  // #if idempotency
  const { store, scope, key } = lease;
  const done = store !== undefined && scope !== undefined && key !== undefined;
  try {
    if (done && res !== null && res.status < 500) {
      const answer: StoredAnswer = { status: res.status, body: res.body };
      const contentType = res.headers['content-type'];
      const etag = res.headers['etag'];
      const location = res.headers['location'];
      if (contentType !== undefined) answer.contentType = contentType;
      if (etag !== undefined) answer.etag = etag;
      if (location !== undefined) answer.location = location;
      try {
        await store.complete(scope, key, answer);
      } catch (err) {
        // A `complete` that fails must not leave the entry running: the key is released.
        storeFailed(lease, err);
        await store.release(scope, key);
      }
    } else if (done) {
      await store.release(scope, key);
    }
  } catch (err) {
    storeFailed(lease, err);
  }
  if (res === null) throw new Error('the request ended without an answer');
  return res;
}
// #endif
// #if headers

/** The step 5 issues of the headers the runtime itself reads: `If-Match` and the idempotency key. */
function headerIssues(ep: EndpointSpec, headers: Headers): Issue[] {
  const out: Issue[] = [];
  // #endif
  // #if version
  out.push(...ifMatchIssues(ep, headers));
  // #endif
  // #if idempotency
  out.push(...keyIssues(ep, headers));
  // #endif
  // #if headers
  return out;
}

/**
 * `422 ValidationError` for a malformed header: its issues come first, then the issues of any rule
 * the body breaks. A header issue is not a rule, so it carries no violation of its own. It is
 * refused even when request validation is off.
 */
function headerRefusal(ep: EndpointSpec, bound: Bound, lead: Issue[], std: StdSigs, hooks: HandlerHooks): VeldResponse {
  // #endif
  // #if headers_rules
  const refused = checkInputRules(ep, bound, std, hooks);
  if (refused !== null && refused.body !== null) {
    const doc = JSON.parse(refused.body) as { data: { issues: Issue[] } };
    doc.data.issues = [...lead, ...doc.data.issues];
    return { ...refused, body: JSON.stringify(doc) };
  }
  // #endif
  // #if headers
  return problem(std.validation, 'ValidationError', 422, ep.sig, { issues: lead });
}

// #endif
// ---------------------------------------------------------------------------
// Server: Server-Sent Events
// ---------------------------------------------------------------------------

export interface SseOptions {
  /** The `event:` name. Omit it for the default `message` event. */
  event?: string;
  /** The `id:` of the event. A reconnecting client sends the last one as `Last-Event-ID`. */
  id?: string;
  /** The `retry:` reconnection delay in milliseconds. */
  retry?: number;
}

/** What a stream implementation yields when it wants to set the event name or id. */
export class SseEvent<T = unknown> {
  readonly veldSse = 1 as const;
  readonly data: T;
  readonly options: SseOptions;

  constructor(data: T, options: SseOptions = {}) {
    this.data = data;
    this.options = options;
  }
}

export function sseEvent<T>(data: T, options: SseOptions = {}): SseEvent<T> {
  return new SseEvent(data, options);
}

function isSseEvent(v: unknown): v is SseEvent {
  return isObject(v) && v['veldSse'] === 1 && 'data' in v;
}

function oneLine(field: string, v: string): string {
  if (/[\r\n]/.test(v)) throw new Error(`SSE ${field} must not contain a line break`);
  return v;
}

/**
 * One Server-Sent Event: the optional `id`, `event` and `retry` fields in that order, then one
 * `data` line, then a blank line. `data` is canonical JSON, which never contains a line break.
 */
export function sseFrame(data: string, o: SseOptions = {}): string {
  let out = '';
  if (o.id !== undefined) out += `id: ${oneLine('id', o.id)}\n`;
  if (o.event !== undefined) out += `event: ${oneLine('event', o.event)}\n`;
  if (o.retry !== undefined) out += `retry: ${Math.trunc(o.retry)}\n`;
  return `${out}data: ${oneLine('data', data)}\n\n`;
}

function sseItem(ep: ServerEndpoint, item: unknown, hooks: HandlerHooks): string {
  const ev = isSseEvent(item) ? item : null;
  // #if not_derived
  const value = ev === null ? item : ev.data;
  // #endif
  // #if derived
  const value = deriveSent(ep.success, ev === null ? item : ev.data);
  // #endif
  if (ep.success === null) throw new Error(`${ep.name}: a stream needs an item type`);
  if (hooks.validateResponses) {
    const issues = validate(ep.success, value);
    if (issues.length > 0) throw new Error(`${ep.name}: stream item failed validation: ${JSON.stringify(issues)}`);
  }
  // #if rules
  checkItemRules(ep, 'stream item', value, hooks);
  // #endif
  // #if tenancy
  checkItemTenant(ep, 'stream item', value, hooks);
  // #endif
  // #if visibility
  return sseFrame(canonicalOf(ep.success, showSent(ep, ep.success, value, hooks)), ev === null ? {} : ev.options);
  // #endif
  // #if not_visibility
  return sseFrame(canonicalOf(ep.success, value), ev === null ? {} : ev.options);
  // #endif
}

async function* noFrames(): AsyncGenerator<string> {
  // An empty stream: the headers go out and the response ends.
}

async function closeIterator(it: AsyncIterator<unknown>): Promise<void> {
  try {
    await it.return?.();
  } catch {
    // Closing is best effort.
  }
}

async function* sseBody(
  ep: ServerEndpoint,
  it: AsyncIterator<unknown>,
  firstFrame: string,
  ctx: RequestContext,
  std: StdSigs,
  hooks: HandlerHooks,
): AsyncGenerator<string> {
  try {
    yield firstFrame;
    for (;;) {
      const step = await it.next();
      if (step.done === true) return;
      yield sseItem(ep, step.value, hooks);
    }
  } catch (err) {
    // The status line is long gone: the error travels as a final `event: error`.
    yield sseFrame(failure(err, ep, ctx, std, hooks).body ?? 'null', { event: 'error' });
  } finally {
    await closeIterator(it);
  }
}

/**
 * Pulls the first item before answering, so that an error raised before any event is a normal
 * problem+json response. After that the status is 200 and errors become the final `error` event.
 */
async function startSse(
  ep: ServerEndpoint,
  source: AsyncIterable<unknown>,
  ctx: RequestContext,
  std: StdSigs,
  hooks: HandlerHooks,
): Promise<VeldResponse> {
  const it = source[Symbol.asyncIterator]();
  let firstFrame: string | null = null;
  try {
    const first = await it.next();
    if (first.done !== true) firstFrame = sseItem(ep, first.value, hooks);
  } catch (err) {
    await closeIterator(it);
    throw err;
  }
  const headers = { 'content-type': 'text/event-stream', 'cache-control': 'no-cache', 'x-accel-buffering': 'no' };
  const frames = firstFrame === null ? noFrames() : sseBody(ep, it, firstFrame, ctx, std, hooks);
  return { status: ep.status, headers, body: null, stream: frames };
}

// ---------------------------------------------------------------------------
// Server: WebSocket
// ---------------------------------------------------------------------------

/** An unbounded async queue: `push` never blocks, iteration waits for the next item or `end()`. */
class Queue<T> {
  private readonly items: T[] = [];
  private readonly waiting: ((r: IteratorResult<T>) => void)[] = [];
  private ended = false;

  push(value: T): void {
    if (this.ended) return;
    const w = this.waiting.shift();
    if (w) w({ done: false, value });
    else this.items.push(value);
  }

  end(): void {
    this.ended = true;
    for (const w of this.waiting.splice(0)) w({ done: true, value: undefined });
  }

  [Symbol.asyncIterator](): AsyncIterator<T> {
    return {
      next: () => {
        if (this.items.length > 0) return Promise.resolve({ done: false, value: this.items.shift() as T });
        if (this.ended) return Promise.resolve({ done: true, value: undefined });
        return new Promise((resolve) => this.waiting.push(resolve));
      },
    };
  }
}

/** What a `ws` endpoint implementation gets: the validated messages of the client and a way to answer. */
export interface WsSession<In = unknown, Out = unknown> {
  /** Messages from the client, validated and decoded. Ends when the socket closes. */
  readonly incoming: AsyncIterable<In>;
  /** Sends one message (canonical JSON). Throws when the socket is closed. */
  send(message: Out): void;
  /** Closes the socket normally. Returning from the implementation does the same. */
  close(): void;
  readonly closed: boolean;
}

/** `Authorization` from `?access_token=` and the API key header from `?api_key=`, when absent. */
function wsHeaders(ep: ServerEndpoint, req: VeldRequest): Headers {
  const h = lowerHeaders(req.headers);
  const q = parseQuery(req.query);
  if (ep.auth?.kind === 'bearer' && h['authorization'] === undefined) {
    const t = q.get('access_token')?.[0];
    if (t !== undefined) h['authorization'] = `Bearer ${t}`;
  }
  const keyHeader = (ep.auth?.header ?? 'X-API-Key').toLowerCase();
  if (ep.auth?.kind === 'api_key' && h[keyHeader] === undefined) {
    const k = q.get('api_key')?.[0];
    if (k !== undefined) h[keyHeader] = k;
  }
  return h;
}

interface WsState {
  closed: boolean;
}

function wsSession(
  ep: ServerEndpoint,
  sock: WsSocket,
  inbox: Queue<unknown>,
  state: WsState,
  hooks: HandlerHooks,
  finish: (code: number, reason: string) => void,
): WsSession {
  return {
    incoming: inbox,
    get closed() {
      return state.closed;
    },
    send(message) {
      if (state.closed) throw new Error(`${ep.name}: the WebSocket is closed`);
      if (ep.success === null) throw new Error(`${ep.name}: this endpoint sends no messages`);
      // #if derived
      message = deriveSent(ep.success, message) as typeof message;
      // #endif
      if (hooks.validateResponses) {
        const issues = validate(ep.success, message);
        if (issues.length > 0) throw new Error(`${ep.name}: message failed validation: ${JSON.stringify(issues)}`);
      }
      // #if rules
      checkItemRules(ep, 'message', message, hooks);
      // #endif
      // #if tenancy
      checkItemTenant(ep, 'message', message, hooks);
      // #endif
      // #if visibility
      sock.send(`{"data":${canonicalOf(ep.success, showSent(ep, ep.success, message, hooks))}}`);
      // #endif
      // #if not_visibility
      sock.send(`{"data":${canonicalOf(ep.success, message)}}`);
      // #endif
    },
    close: () => finish(1000, 'closed'),
  };
}

async function runWs(
  r: Route,
  m: RegExpExecArray,
  req: VeldRequest,
  sock: WsSocket,
  std: StdSigs,
  hooks: HandlerHooks,
): Promise<void> {
  const ep = r.ep;
  const ctx = contextOf(ep, req, wsHeaders(ep, req));
  // #if flags
  hooks = withFlagState(hooks);
  // #endif
  // #if platform
  hooks = platformOpen(hooks, ctx);
  // #endif
  const incomingSchema = ep.params.find((p) => p.s === true)?.t;
  const inbox = new Queue<unknown>();
  const state: WsState = { closed: false };
  const finish = (code: number, reason: string): void => {
    if (state.closed) return;
    state.closed = true;
    inbox.end();
    sock.close(code, reason);
  };
  const fail = (res: VeldResponse): void => {
    if (state.closed) return;
    sock.send(`{"error":${res.body ?? 'null'}}`);
    finish(res.status >= 500 ? 1011 : 1008, `problem ${res.status}`);
  };
  const invalid = (issues: Issue[]): void => {
    fail(problem(std.validation, 'ValidationError', 422, ep.sig, { issues }));
  };
  const accept = (text: string): void => {
    if (incomingSchema === undefined) {
      return invalid([{ path: 'message', code: 'unexpected', message: 'this endpoint does not accept messages' }]);
    }
    let raw: unknown;
    try {
      raw = JSON.parse(text) as unknown;
    } catch {
      return invalid([{ path: 'message', code: 'json', message: 'message is not valid JSON' }]);
    }
    const issues =
      hooks.validateRequests === false ? [] : validate(incomingSchema, raw, 'message', { wire: true, request: true });
    if (issues.length > 0) return invalid(issues);
    // #if rules
    const refused = checkMessageRules(ep, incomingSchema, raw, std, hooks);
    if (refused !== null) return fail(refused);
    // #endif
    // #if not_derived
    inbox.push(fromWire(incomingSchema, raw, { request: true }));
    // #endif
    // #if derived
    const failed: Violation[] = [];
    const message = deriveNode(incomingSchema, fromWire(incomingSchema, raw, { request: true }), 'message', failed, false);
    // With request validation on, `checkMessageRules` has refused a failure already.
    if (failed.length > 0) return fail(rulesProblem(ep, failed, std));
    inbox.push(message);
    // #endif
  };
  // Frames that arrive while auth and middleware run are held back, so they are never read by an
  // unauthenticated session and never lost.
  const early: string[] = [];
  let ready = false;
  sock.onMessage((text) => (ready ? accept(text) : early.push(text)));
  sock.onClose(() => {
    state.closed = true;
    inbox.end();
  });
  try {
    const bound = await guard(r, m, req, ctx, std, hooks, true);
    if (isResponse(bound)) return fail(bound);
    ready = true;
    for (const text of early.splice(0)) accept(text);
    await ep.call(bound.value, ctx, wsSession(ep, sock, inbox, state, hooks, finish));
    finish(1000, 'done');
  } catch (err) {
    fail(failure(err, ep, ctx, std, hooks));
  }
}

function assertHooks(endpoints: readonly ServerEndpoint[], hooks: HandlerHooks): void {
  const authKey = { bearer: 'bearer', basic: 'basic', api_key: 'apiKey' } as const;
  for (const ep of endpoints) {
    if (ep.auth && !hooks.auth?.[authKey[ep.auth.kind]]) {
      throw new Error(`${ep.name}: hooks.auth.${authKey[ep.auth.kind]} is required`);
    }
    for (const name of ep.middleware) {
      if (!hooks.middleware?.[name]) throw new Error(`${ep.name}: hooks.middleware.${name} is required`);
    }
    // #if flags
    if (ep.flags !== undefined && ep.flags.length > 0 && hooks.flags === undefined) {
      throw new Error(`${ep.name}: hooks.flags is required`);
    }
    // #endif
    // #if limits_server
    assertLimitHooks(ep, hooks);
    // #endif
    // #if audit
    if (ep.audit !== undefined && hooks.audit === undefined) {
      throw new Error(`${ep.name}: hooks.audit is required`);
    }
    // #endif
    // #if outbox
    if (ep.rules?.transition?.emits !== undefined && hooks.outbox === undefined) {
      throw new Error(`${ep.name}: hooks.outbox is required`);
    }
    // #endif
    // #if idempotency
    if (ep.idempotency !== undefined) {
      if (!hooks.idempotency?.store) throw new Error(`${ep.name}: hooks.idempotency.store is required`);
      if (ep.idempotency.caller && !hooks.idempotency.caller) throw new Error(`${ep.name}: hooks.idempotency.caller is required`);
    }
    // #endif
  }
}

/** Builds a handler from endpoint descriptions. Matching is exact; literal routes beat parameterised ones. */
export function createHandler(endpoints: readonly ServerEndpoint[], std: StdSigs, hooks: HandlerHooks): VeldHandler {
  assertHooks(endpoints, hooks);
  // #if limits_server
  hooks = withLimiter(endpoints, hooks);
  // #endif
  // #if rules
  reportRuleMode(hooks, endpoints);
  const run = (r: Route, m: RegExpExecArray, req: VeldRequest, sigs: StdSigs, opts: HandlerHooks): Promise<VeldResponse> =>
    runRoute(r, m, req, sigs, opts).then((res) => withDigest(r.ep, res));
  // #endif
  // #if endpoint_rules
  reportEndpointRules(hooks, endpoints);
  // #endif
  const routes = endpoints.map(compileRoute).sort((a, b) => a.names.length - b.names.length);
  const find = (method: string, rawPath: string): { r: Route; m: RegExpExecArray } | null => {
    const path = normalizePath(rawPath);
    for (const r of routes) {
      if (r.ep.method !== method) continue;
      const m = r.re.exec(path);
      if (m) return { r, m };
    }
    return null;
  };
  // #if bounded_plain
  const exec = bound(run);
  // #endif
  // #if audit_unbounded
  const exec = withAudit(run);
  // #endif
  // #if audit_bounded
  const exec = withAudit(bound(run));
  // #endif
  const handler = async (req: VeldRequest): Promise<VeldResponse | null> => {
    const hit = find(req.method.toUpperCase(), req.path);
    // #if not_execs
    return hit === null ? null : run(hit.r, hit.m, req, std, hooks);
    // #endif
    // #if execs
    return hit === null ? null : exec(hit.r, hit.m, req, std, hooks);
    // #endif
  };
  const ws = async (req: VeldRequest, socket: WsSocket): Promise<boolean> => {
    const hit = find('WS', req.path);
    if (hit === null) return false;
    await runWs(hit.r, hit.m, req, socket, std, hooks);
    return true;
  };
  return Object.assign(handler, { ws });
}

// ---------------------------------------------------------------------------
// Client core
// ---------------------------------------------------------------------------

export interface FetchInit {
  method: string;
  headers: Record<string, string>;
  body?: string;
  signal?: AbortSignalLike;
}

export interface StreamReaderLike {
  read(): Promise<{ done: boolean; value?: Uint8Array }>;
  cancel(reason?: unknown): Promise<void>;
}

export interface FetchResponse {
  status: number;
  text(): Promise<string>;
  /** The response body as a byte stream (`fetch` in browsers and Node 18+). Needed for SSE. */
  body?: { getReader(): StreamReaderLike } | null;
  // #if rules
  /** The response headers (`fetch` has them). The rules digest is read from here. */
  headers?: { get(name: string): string | null };
  // #endif
}

export interface AbortSignalLike {
  readonly aborted: boolean;
  addEventListener?(type: 'abort', listener: () => void): void;
}

/** Structural `fetch`: the global `fetch` is assignable to it. */
export type FetchLike = { bivarianceHack(url: string, init: FetchInit): Promise<FetchResponse> }['bivarianceHack'];

/** The part of the WebSocket API the client uses: the global `WebSocket` of browsers and Node 22 fits. */
export interface WsClientLike {
  readonly readyState: number;
  send(data: string): void;
  close(code?: number, reason?: string): void;
  onopen: ((ev: unknown) => void) | null;
  onmessage: ((ev: { data: unknown }) => void) | null;
  onclose: ((ev: { code: number; reason: string }) => void) | null;
  onerror: ((ev: unknown) => void) | null;
}

export type WsConstructor = new (url: string) => WsClientLike;

export interface BasicCredentials {
  username: string;
  password: string;
}

type Headers_ = Record<string, string>;

export interface ClientOptions {
  // #if runtime_config
  /** The address of the service (`services.<service>.url` of the runtime config). A trailing `/` is dropped. */
  baseUrl: string;
  // #endif
  // #if not_runtime_config
  baseUrl?: string;
  // #endif
  fetch?: FetchLike;
  /** The WebSocket constructor for `ws` endpoints. Default: the global `WebSocket`. */
  webSocket?: WsConstructor;
  headers?: Headers_ | (() => Headers_ | Promise<Headers_>);
  auth?: {
    bearer?: () => string | Promise<string>;
    basic?: () => BasicCredentials | Promise<BasicCredentials>;
    apiKey?: () => string | Promise<string>;
  };
  /** Validate requests (and outgoing WebSocket messages) before sending them. Default: true. */
  validate?: boolean;
  // #if limits
  /**
   * Wait and send again, once, when a `get` or an `@idempotent` call is refused with `429` and
   * `retryAfter` (spec/platform.md section 5). Default: true. Other calls raise the typed error at once.
   */
  retryOnLimit?: boolean;
  /** How the client waits before it sends again: milliseconds. Default: a timer, which an abort ends. A test passes one that does not wait. */
  sleep?: (ms: number) => Promise<void>;
  // #endif
  // #if rules
  /** Check the invariants of a request body and query object before sending. Default: true. */
  rules?: boolean;
  /**
   * Called once per rules digest this client had not seen, when a response carries a digest other
   * than the client's own: the server's rules changed since the client was generated, so the local
   * checks of that service stop.
   */
  onContractMismatch?: (info: ContractMismatch) => void;
  // #endif
}

// #if rules
export interface ContractMismatch {
  /** The service name. */
  service: string;
  /** The digest this client was generated with. */
  clientDigest: string;
  /** The digest the server sent in `Veld-Rules`. */
  serverDigest: string;
}

// #endif
export interface CallInit {
  signal?: AbortSignalLike;
  // #if timeouts
  /**
   * The most a call may take, in milliseconds: it fails with a `VeldTransportError` when the answer
   * has not arrived. Default: the `@timeout` of the endpoint, when it has one.
   */
  timeoutMs?: number;
  // #endif
}

/**
 * Reconnect with exponential backoff after a connection failure (a refused or broken connection,
 * an abnormal WebSocket close). A typed error, a normal end of the stream and an abort never
 * reconnect. Off unless given; the React and Vue hooks turn it on by default.
 */
export interface Reconnect {
  /** Delay before the first retry. Default: 1000. */
  initialMs?: number;
  /** The delay doubles after every failed attempt up to this. Default: 30000. */
  maxMs?: number;
  /** Consecutive failed attempts before the failure is thrown. Default: 10. */
  retries?: number;
}

/** `reconnect` of a streaming call: a policy, or `false` to switch off the default of a hook. */
export interface ReconnectInit {
  reconnect?: Reconnect | false;
}

interface ReconnectPolicy {
  initialMs: number;
  maxMs: number;
  retries: number;
}

function reconnectPolicy(r: Reconnect | false | undefined): ReconnectPolicy | null {
  if (r === undefined || r === false) return null;
  return { initialMs: r.initialMs ?? 1000, maxMs: r.maxMs ?? 30000, retries: r.retries ?? 10 };
}

/** The delay before retry number `attempt` (0-based): `initialMs` doubling up to `maxMs`. */
export function backoffMs(policy: Reconnect, attempt: number): number {
  const initial = policy.initialMs ?? 1000;
  const max = policy.maxMs ?? 30000;
  return Math.min(max, initial * 2 ** Math.min(attempt, 30));
}

/** Errors that mean "the connection failed", as opposed to a typed or protocol error. */
const RETRYABLE = new WeakSet<object>();

function retryable<E extends object>(e: E): E {
  RETRYABLE.add(e);
  return e;
}

function isAborted(signal: AbortSignalLike | undefined): boolean {
  return signal?.aborted === true;
}

function sleep(ms: number, signal: AbortSignalLike | undefined): Promise<void> {
  type Timer = (fn: () => void, ms: number) => unknown;
  const set = (globalThis as { setTimeout?: Timer }).setTimeout;
  return new Promise((resolve) => {
    if (!set) return resolve();
    const t = set(resolve, ms);
    signal?.addEventListener?.('abort', () => {
      (globalThis as { clearTimeout?: (t: unknown) => void }).clearTimeout?.(t);
      resolve();
    });
  });
}

/** Options of a Server-Sent Events call. */
export interface StreamInit extends CallInit, ReconnectInit {
  /** Sent as `Last-Event-ID`, to resume after the last event a previous call delivered. */
  lastEventId?: string;
  /** Called with the `id` of every event that has one. */
  onEventId?: (id: string) => void;
}

/** Options of a WebSocket call. Aborting the signal closes the socket. */
export interface WsInit extends CallInit, ReconnectInit {}

/**
 * A WebSocket endpoint seen from the client. Iterate it for the server's messages: it ends when
 * the server closes normally and throws the typed error of an error frame. `send` validates and
 * queues until the socket is open.
 */
export interface WsChannel<In, Out> extends AsyncIterable<In> {
  send(message: Out): void;
  close(): void;
}

export interface ClientDefaults {
  // #if not_runtime_config
  /** Environment variable consulted for the base URL, e.g. `VELD_ORDERS_URL`. */
  envVar: string;
  /** Base URL baked in from the contract. */
  baseUrl: string | null;
  // #endif
  /** Builds the local `ValidationError`. */
  validation(issues: Issue[]): VeldError;
  // #if rules
  /** The service name, for `onContractMismatch`. */
  service?: string;
  /** The rules digest of the service this client was generated from (spec/rules.md section 9.7). */
  digest?: string;
  // #endif
}

// #if not_runtime_config
function envValue(name: string): string | undefined {
  const g = globalThis as { process?: { env?: Record<string, string | undefined> } };
  return g.process?.env?.[name];
}
// #endif

function scalarString(v: unknown): string {
  return typeof v === 'string' ? v : String(v);
}

function requestIssues(ep: EndpointSpec, req: Record<string, unknown>): Issue[] {
  const out: Issue[] = [];
  for (const p of ep.params) {
    if (p.s) continue;
    const v = req[p.name];
    if (v === undefined) {
      if (!p.o) push(out, paramLoc(p), 'required', 'is required');
    } else {
      out.push(...validate(p.t, v, paramLoc(p)));
    }
  }
  return out;
}

function queryPairs(ep: EndpointSpec, req: Record<string, unknown>): [string, string][] {
  const pairs: [string, string][] = [];
  const add = (key: string, v: unknown): void => {
    if (v === undefined) return;
    for (const x of Array.isArray(v) ? v : [v]) pairs.push([key, scalarString(x)]);
  };
  for (const p of ep.params) {
    const v = req[p.name];
    if (p.binding === 'query') add(p.name, v);
    if (p.binding === 'query_object' && v !== undefined) {
      // #if not_derived
      const wire = toWire(p.t, v);
      // #endif
      // #if derived
      const wire = toWireSend(p.t, v);
      // #endif
      if (isObject(wire)) for (const k of Object.keys(wire)) add(k, wire[k]);
    }
  }
  return pairs.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
}

// -- Server-Sent Events parsing ------------------------------------------------

export interface SseMessage {
  /** The `event:` name, `message` when the event had none. */
  event: string;
  /** The `data:` lines joined with `\n`. */
  data: string;
  /** The last `id:` seen so far, if any. */
  id: string | undefined;
}

/**
 * Incremental parser of a `text/event-stream` body (WHATWG HTML section 9.2): lines end in `\n`,
 * `\r\n` or `\r`, `:` lines are comments, a blank line dispatches the event, an event without
 * `data` is dropped, and an event cut off by the end of the stream is discarded.
 */
export class SseParser {
  private buf = '';
  private data: string[] = [];
  private event = '';
  private id: string | undefined;
  private first = true;

  push(chunk: string): SseMessage[] {
    this.buf += chunk;
    if (this.first && this.buf.length > 0) {
      this.first = false;
      if (this.buf.charCodeAt(0) === 0xfeff) this.buf = this.buf.slice(1);
    }
    const out: SseMessage[] = [];
    let start = 0;
    for (;;) {
      let end = start;
      while (end < this.buf.length && this.buf[end] !== '\n' && this.buf[end] !== '\r') end++;
      if (end >= this.buf.length) break;
      // A trailing `\r` may be the first half of `\r\n`: wait for the next chunk.
      if (this.buf[end] === '\r' && end + 1 >= this.buf.length) break;
      this.line(this.buf.slice(start, end), out);
      start = end + (this.buf[end] === '\r' && this.buf[end + 1] === '\n' ? 2 : 1);
    }
    this.buf = this.buf.slice(start);
    return out;
  }

  private line(line: string, out: SseMessage[]): void {
    if (line === '') {
      if (this.data.length > 0) out.push({ event: this.event === '' ? 'message' : this.event, data: this.data.join('\n'), id: this.id });
      this.data = [];
      this.event = '';
      return;
    }
    if (line.startsWith(':')) return;
    const colon = line.indexOf(':');
    const field = colon < 0 ? line : line.slice(0, colon);
    let value = colon < 0 ? '' : line.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    if (field === 'data') this.data.push(value);
    else if (field === 'event') this.event = value;
    else if (field === 'id' && !value.includes('\u0000')) this.id = value;
  }
}

interface Linked {
  signal: AbortSignalLike;
  abort(): void;
}

/** A signal that aborts when `user` does and when `abort()` is called. */
function linkAbort(user: AbortSignalLike | undefined): Linked {
  type Ctor = new () => { signal: AbortSignalLike; abort(): void };
  const Controller = (globalThis as { AbortController?: Ctor }).AbortController;
  if (!Controller) return { signal: user ?? { aborted: false }, abort: () => undefined };
  const c = new Controller();
  if (user?.aborted === true) c.abort();
  else user?.addEventListener?.('abort', () => c.abort());
  return c;
}

// #if timeouts
interface CallLimit {
  signal: AbortSignalLike;
  ms: number;
  expired(): boolean;
  clear(): void;
}

/** The timeout of a call (the caller's, else the endpoint's) as a signal that aborts when it passes. `null` without one. */
function callLimit(ep: EndpointSpec, init: CallInit): CallLimit | null {
  const ms = init.timeoutMs ?? ep.timeoutMs;
  const api = globalThis as { setTimeout?: (fn: () => void, ms: number) => unknown; clearTimeout?: (t: unknown) => void };
  if (ms === undefined || api.setTimeout === undefined) return null;
  const link = linkAbort(init.signal);
  let hit = false;
  const timer = api.setTimeout(() => {
    hit = true;
    link.abort();
  }, ms);
  return { signal: link.signal, ms, expired: () => hit, clear: () => api.clearTimeout?.(timer) };
}

// #endif
interface TextDecoderLike {
  decode(input?: Uint8Array, options?: { stream?: boolean }): string;
}

type WsEvent = { ok: unknown } | { err: unknown };

// #if limits
/** The `retryAfter` (seconds) of the data of a `429` problem document, or `undefined` when it has none. */
function retryAfterOf(text: string): number | undefined {
  try {
    const doc = JSON.parse(text) as unknown;
    const data = isObject(doc) ? doc['data'] : undefined;
    const seconds = isObject(data) ? data['retryAfter'] : undefined;
    return typeof seconds === 'number' && Number.isFinite(seconds) ? seconds : undefined;
  } catch {
    return undefined;
  }
}

/** The answer that was read, as one that can be read again. */
function readAgain(res: FetchResponse, text: string): FetchResponse {
  const out: FetchResponse = { status: res.status, text: () => Promise.resolve(text) };
  // #endif
  // #if limits_rules
  if (res.headers !== undefined) out.headers = res.headers;
  // #endif
  // #if limits
  return out;
}

// #endif
export class ClientCore {
  private readonly baseUrl: string;
  private readonly doFetch: FetchLike;

  constructor(
    private readonly opts: ClientOptions,
    private readonly defaults: ClientDefaults,
  ) {
    // #if runtime_config
    const base: unknown = opts.baseUrl;
    if (typeof base !== 'string' || base === '') {
      throw new VeldTransportError('no base URL: pass baseUrl');
    }
    // #endif
    // #if not_runtime_config
    const base = opts.baseUrl ?? envValue(defaults.envVar) ?? defaults.baseUrl;
    if (base === null || base === undefined) {
      throw new VeldTransportError(`no base URL: pass baseUrl or set ${defaults.envVar}`);
    }
    // #endif
    this.baseUrl = base.replace(/\/+$/, '');
    const f = opts.fetch ?? (globalThis as { fetch?: FetchLike }).fetch;
    if (!f) throw new VeldTransportError('no fetch implementation: pass options.fetch');
    this.doFetch = f;
  }

  private check(ep: EndpointSpec, req: Record<string, unknown>): void {
    if (this.opts.validate === false) return;
    const issues = requestIssues(ep, req);
    if (issues.length > 0) {
      const err = this.defaults.validation(issues);
      err.op = ep.sig;
      throw err;
    }
    // #if rules
    this.checkRules(ep, req);
    // #endif
  }
  // #if rules

  private checkRules(ep: EndpointSpec, req: Record<string, unknown>): void {
    if (this.opts.rules === false) return;
    const out: Violation[] = [];
    for (const p of ep.params) {
      if (p.s || (p.binding !== 'body' && p.binding !== 'query_object')) continue;
      const v = req[p.name];
      // #endif
      // #if derived
      if (v !== undefined) walkRules(p.t, withDerived(p.t, v, paramLoc(p), out, true), paramLoc(p), 'request', out);
      // #endif
      // #if rules_not_derived
      if (v !== undefined) walkRules(p.t, withDefaults(p.t, v), paramLoc(p), 'request', out);
      // #endif
      // #if rules
    }
    this.rejectLocally(ep, out);
  }

  /** A message the client is about to send on a WebSocket is an input: checked like a request body. */
  private checkMessageRules(ep: EndpointSpec, schema: Schema, message: unknown): void {
    if (this.opts.rules === false) return;
    const out: Violation[] = [];
    // #endif
    // #if derived
    walkRules(schema, withDerived(schema, message, 'message', out, true), 'message', 'request', out);
    // #endif
    // #if rules_not_derived
    walkRules(schema, withDefaults(schema, message), 'message', 'request', out);
    // #endif
    // #if rules
    this.rejectLocally(ep, out);
  }

  private rejectLocally(ep: EndpointSpec, out: Violation[]): void {
    if (out.length === 0 || !this.rulesTrusted()) return;
    const err = this.defaults.validation(ruleIssues(out));
    err.violations = out;
    err.local = true;
    err.op = ep.sig;
    throw err;
  }

  /** The digest the last response of this service carried, `undefined` before the first one. */
  private serverDigest: string | undefined;
  private readonly seenDigests = new Set<string>();

  /** Local rule checks reject only while the server's digest is ours (spec/rules.md section 9.7). */
  private rulesTrusted(): boolean {
    const own = this.defaults.digest;
    return own === undefined || this.serverDigest === own;
  }

  /** Remembers the digest of a response, and reports a digest this client has not seen once. */
  private observe(res: FetchResponse): void {
    const own = this.defaults.digest;
    if (own === undefined) return;
    const seen = res.headers?.get('veld-rules') ?? undefined;
    this.serverDigest = seen;
    if (seen === undefined || seen === own || this.seenDigests.has(seen)) return;
    this.seenDigests.add(seen);
    try {
      this.opts.onContractMismatch?.({ service: this.defaults.service ?? '', clientDigest: own, serverDigest: seen });
    } catch {
      // A failing hook must not change the outcome of the call.
    }
  }
  // #endif

  async call(ep: EndpointSpec, input: object, init: CallInit = {}): Promise<unknown> {
    const req = input as Record<string, unknown>;
    this.check(ep, req);
    // #if timeouts
    const limit = callLimit(ep, init);
    if (limit !== null) init = { ...init, signal: limit.signal };
    try {
    // #endif
    // #if limits
    const res = await this.sendLimited(ep, req, init);
    // #endif
    // #if not_limits
    const res = await this.send(ep, req, init, {});
    // #endif
    // #if rules
    this.observe(res);
    // #endif
    // #if not_timeouts
    return this.decode(ep, res);
    // #endif
    // #if timeouts
    return await this.decode(ep, res);
    } catch (err) {
      if (limit?.expired() === true) {
        throw new VeldTransportError(`${ep.method} ${ep.path} timed out after ${String(limit.ms)} ms`, err);
      }
      throw err;
    } finally {
      limit?.clear();
    }
    // #endif
  }

  /**
   * Server-Sent Events: an `AsyncIterable` that opens the request when iteration starts. It ends
   * when the server ends the stream or the signal aborts, and throws the typed error of a failed
   * response or of a final `error` event. There is no automatic reconnect unless `init.reconnect`
   * is given: then a broken or refused connection is retried with exponential backoff, resuming
   * with `Last-Event-ID`. Otherwise call again with `lastEventId` to resume.
   */
  stream(ep: EndpointSpec, input: object, init: StreamInit = {}): AsyncIterable<unknown> {
    const req = input as Record<string, unknown>;
    return { [Symbol.asyncIterator]: () => this.events(ep, req, init) };
  }

  private async *events(ep: EndpointSpec, req: Record<string, unknown>, init: StreamInit): AsyncGenerator<unknown> {
    this.check(ep, req);
    const policy = reconnectPolicy(init.reconnect);
    let lastId = init.lastEventId;
    let failures = 0;
    for (;;) {
      let delivered = false;
      try {
        yield* this.eventsOnce(ep, req, {
          ...(init.signal ? { signal: init.signal } : {}),
          ...(lastId === undefined ? {} : { lastEventId: lastId }),
          onEventId: (id) => {
            lastId = id;
            init.onEventId?.(id);
          },
          onItem: () => {
            delivered = true;
          },
        });
        return;
      } catch (err) {
        const again = typeof err === 'object' && err !== null && RETRYABLE.has(err);
        if (policy === null || !again || isAborted(init.signal)) throw err;
        if (delivered) failures = 0;
        if (failures >= policy.retries) throw err;
        await sleep(backoffMs(policy, failures), init.signal);
        failures += 1;
        if (isAborted(init.signal)) return;
      }
    }
  }

  private async *eventsOnce(
    ep: EndpointSpec,
    req: Record<string, unknown>,
    init: StreamInit & { onItem: () => void },
  ): AsyncGenerator<unknown> {
    const link = linkAbort(init.signal);
    let reader: StreamReaderLike | undefined;
    try {
      const extra: Headers_ = init.lastEventId === undefined ? {} : { 'last-event-id': init.lastEventId };
      const res = await this.send(ep, req, { signal: link.signal }, { accept: 'text/event-stream', extra });
      // #if rules
      this.observe(res);
      // #endif
      if (res.status < 200 || res.status >= 300) await this.decode(ep, res);
      if (!res.body) throw new VeldTransportError(`${ep.method} ${ep.path}: the response has no body stream`);
      reader = res.body.getReader();
      const Decoder = (globalThis as { TextDecoder?: new () => TextDecoderLike }).TextDecoder;
      if (!Decoder) throw new VeldTransportError('no TextDecoder: streaming needs a modern runtime');
      const decoder = new Decoder();
      const parser = new SseParser();
      for (;;) {
        let chunk: { done: boolean; value?: Uint8Array };
        try {
          chunk = await reader.read();
        } catch (cause) {
          if (link.signal.aborted) return;
          throw retryable(new VeldTransportError(`${ep.method} ${ep.path}: the stream broke`, cause));
        }
        if (chunk.done) return;
        for (const message of parser.push(decoder.decode(chunk.value, { stream: true }))) {
          if (message.id !== undefined) init.onEventId?.(message.id);
          const value = this.eventValue(ep, message);
          init.onItem();
          yield value;
        }
      }
    } catch (err) {
      if (link.signal.aborted) return;
      throw err;
    } finally {
      link.abort();
      await reader?.cancel().catch(() => undefined);
    }
  }

  private eventValue(ep: EndpointSpec, message: SseMessage): unknown {
    let body: unknown;
    try {
      body = JSON.parse(message.data) as unknown;
    } catch (cause) {
      throw new VeldTransportError(`${ep.method} ${ep.path}: an event is not valid JSON`, cause);
    }
    if (message.event === 'error') throw this.errorFor(ep, decodeProblem(body)?.status ?? 0, body);
    if (ep.success === null) throw new VeldTransportError(`${ep.method} ${ep.path}: the stream has no item type`);
    return fromWire(ep.success, body);
  }

  /**
   * WebSocket: opens the socket straight away and returns the channel. Auth goes in the query
   * string (`access_token` for bearer, `api_key` for an API key) because browsers cannot set
   * headers on a WebSocket; `@header` parameters travel as query parameters too.
   */
  connect(ep: EndpointSpec, input: object, init: WsInit = {}): WsChannel<unknown, unknown> {
    const req = input as Record<string, unknown>;
    this.check(ep, req);
    const Socket = this.opts.webSocket ?? (globalThis as { WebSocket?: WsConstructor }).WebSocket;
    if (!Socket) throw new VeldTransportError('no WebSocket implementation: pass options.webSocket');
    const outgoing = ep.params.find((p) => p.s === true)?.t;
    const events = new Queue<WsEvent>();
    const outbox: string[] = [];
    let socket: WsClientLike | undefined;
    let ended = false;
    const end = (): void => {
      if (ended) return;
      ended = true;
      events.end();
    };
    const fail = (err: unknown): void => {
      events.push({ err });
      end();
    };
    const link = linkAbort(init.signal);
    const close = (): void => {
      end();
      link.abort();
      socket?.close(1000, 'client closed');
    };
    let sawError = false;
    const onFrame = (text: string): void => {
      try {
        const frame = JSON.parse(text) as unknown;
        if (isObject(frame) && 'error' in frame) {
          const body = frame['error'];
          events.push({ err: this.errorFor(ep, decodeProblem(body)?.status ?? 0, body) });
          sawError = true;
        } else if (isObject(frame) && 'data' in frame && ep.success !== null) {
          events.push({ ok: fromWire(ep.success, frame['data']) });
        } else {
          fail(new VeldTransportError(`${ep.method} ${ep.path}: unrecognised frame`));
        }
      } catch (cause) {
        fail(new VeldTransportError(`${ep.method} ${ep.path}: a frame is not valid JSON`, cause));
      }
    };
    const policy = reconnectPolicy(init.reconnect);
    let failures = 0;
    // A connection failure: retry with backoff when a policy is set and attempts remain, else fail.
    const lost = (err: Error): void => {
      if (ended) return;
      if (policy === null || failures >= policy.retries) return fail(err);
      const delay = backoffMs(policy, failures);
      failures += 1;
      sleep(delay, init.signal)
        .then(() => (ended ? undefined : open()))
        .catch(fail);
    };
    const open = async (): Promise<void> => {
      const url = await this.wsUrl(ep, req);
      if (ended) return;
      const s = new Socket(url);
      socket = s;
      let connected = false;
      let handled = false;
      let openedAt = 0;
      const failed = (err: Error): void => {
        if (handled || socket !== s) return;
        handled = true;
        // A connection that lived at least `maxMs` (or delivered a frame) was a healthy one: start counting again.
        if (policy !== null && connected && Date.now() - openedAt >= policy.maxMs) failures = 0;
        lost(err);
      };
      s.onopen = () => {
        connected = true;
        openedAt = Date.now();
        for (const text of outbox.splice(0)) s.send(text);
      };
      s.onmessage = (ev) => {
        failures = 0;
        onFrame(typeof ev.data === 'string' ? ev.data : String(ev.data));
      };
      // Some runtimes report a refused connection as `error` alone, with no `close` after it.
      s.onerror = () => {
        if (!connected) failed(new VeldTransportError(`${ep.method} ${ep.path}: could not connect`));
      };
      s.onclose = (ev) => {
        if (ended) return;
        if (sawError || ev.code === 1000 || ev.code === 1005) return end();
        failed(new VeldTransportError(`${ep.method} ${ep.path}: the WebSocket closed (code ${ev.code})`));
      };
    };
    open().catch(fail);
    if (init.signal) {
      if (init.signal.aborted) close();
      else init.signal.addEventListener?.('abort', close);
    }
    return {
      send: (message) => {
        if (ended) throw new VeldTransportError(`${ep.method} ${ep.path}: the WebSocket is closed`);
        if (outgoing === undefined) throw new VeldTransportError(`${ep.method} ${ep.path}: this endpoint takes no messages`);
        if (this.opts.validate !== false) {
          const issues = validate(outgoing, message, 'message');
          if (issues.length > 0) {
            const err = this.defaults.validation(issues);
            err.op = ep.sig;
            throw err;
          }
          // #if rules
          this.checkMessageRules(ep, outgoing, message);
          // #endif
        }
        // #if not_derived
        const text = canonicalOf(outgoing, message);
        // #endif
        // #if derived
        const text = canonicalSend(outgoing, message);
        // #endif
        if (socket !== undefined && socket.readyState === 1) socket.send(text);
        else outbox.push(text);
      },
      close,
      [Symbol.asyncIterator]: () => drain(events),
    };
  }

  private async wsUrl(ep: EndpointSpec, req: Record<string, unknown>): Promise<string> {
    const path = ep.path.replace(/\{([^}]+)\}/g, (_, name: string) => encodeURIComponent(scalarString(req[name])));
    const pairs = queryPairs(ep, req);
    for (const p of ep.params) {
      const v = req[p.name];
      if (p.binding === 'header' && v !== undefined) pairs.push([p.header ?? p.name, scalarString(v)]);
    }
    const auth = this.opts.auth;
    if (ep.auth?.kind === 'bearer' && auth?.bearer) pairs.push(['access_token', await auth.bearer()]);
    if (ep.auth?.kind === 'api_key' && auth?.apiKey) pairs.push(['api_key', await auth.apiKey()]);
    if (ep.auth?.kind === 'basic') {
      throw new VeldTransportError(`${ep.name}: basic auth cannot be sent on a WebSocket; use bearer or an API key`);
    }
    const qs = pairs.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&');
    return `${this.baseUrl.replace(/^http/, 'ws')}${path}${qs === '' ? '' : `?${qs}`}`;
  }

  private async headers(ep: EndpointSpec, req: Record<string, unknown>, accept: string, extra: Headers_): Promise<Headers_> {
    const configured = this.opts.headers;
    const out: Headers_ = { accept, ...(typeof configured === 'function' ? await configured() : configured), ...extra };
    for (const p of ep.params) {
      const v = req[p.name];
      if (p.binding === 'header' && v !== undefined) out[p.header ?? p.name] = scalarString(v);
    }
    // #if version
    if (ep.ifMatch === true && req['ifMatch'] !== undefined) out['If-Match'] = ifMatchText(req['ifMatch']);
    // #endif
    // #if idempotency
    if (ep.idempotency !== undefined && req['idempotencyKey'] !== undefined) {
      out[ep.idempotency.header] = scalarString(req['idempotencyKey']);
    }
    // #endif
    const auth = this.opts.auth;
    if (ep.auth?.kind === 'bearer' && auth?.bearer) out['authorization'] = `Bearer ${await auth.bearer()}`;
    if (ep.auth?.kind === 'basic' && auth?.basic) {
      const c = await auth.basic();
      out['authorization'] = `Basic ${base64Encode(`${c.username}:${c.password}`)}`;
    }
    if (ep.auth?.kind === 'api_key' && auth?.apiKey) out[ep.auth.header ?? 'X-API-Key'] = await auth.apiKey();
    return out;
  }

  // #if limits
  /**
   * `send`, and once more after `retryAfter` seconds when the server refused the call with `429`
   * and the endpoint is a `get` or `@idempotent` (spec/platform.md section 5). Anything else is
   * answered as it came, so the typed error is raised at once.
   */
  private async sendLimited(ep: EndpointSpec, req: Record<string, unknown>, init: CallInit): Promise<FetchResponse> {
    const first = await this.send(ep, req, init, {});
    if (first.status !== 429 || ep.retryOnLimit !== true || this.opts.retryOnLimit === false) return first;
    let text: string;
    try {
      text = await first.text();
    } catch (cause) {
      throw new VeldTransportError(`${ep.method} ${ep.path}: could not read the response`, cause);
    }
    const seconds = retryAfterOf(text);
    if (seconds === undefined) return readAgain(first, text);
    const ms = Math.max(0, seconds) * 1000;
    await (this.opts.sleep === undefined ? sleep(ms, init.signal) : this.opts.sleep(ms));
    return this.send(ep, req, init, {});
  }

  // #endif
  private async send(
    ep: EndpointSpec,
    req: Record<string, unknown>,
    init: CallInit,
    more: { accept?: string; extra?: Headers_ },
  ): Promise<FetchResponse> {
    const path = ep.path.replace(/\{([^}]+)\}/g, (_, name: string) => encodeURIComponent(scalarString(req[name])));
    const qs = queryPairs(ep, req)
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
      .join('&');
    const headers = await this.headers(ep, req, more.accept ?? 'application/json', more.extra ?? {});
    const bodyParam = ep.params.find((p) => p.binding === 'body' && p.s !== true);
    const bodyValue = bodyParam ? req[bodyParam.name] : undefined;
    const fetchInit: FetchInit = { method: ep.method, headers };
    if (bodyParam && bodyValue !== undefined) {
      headers['content-type'] = 'application/json';
      // #if not_derived
      fetchInit.body = JSON.stringify(toWire(bodyParam.t, bodyValue));
      // #endif
      // #if derived
      fetchInit.body = JSON.stringify(toWireSend(bodyParam.t, bodyValue));
      // #endif
    }
    if (init.signal) fetchInit.signal = init.signal;
    try {
      return await this.doFetch(`${this.baseUrl}${path}${qs === '' ? '' : `?${qs}`}`, fetchInit);
    } catch (cause) {
      throw retryable(new VeldTransportError(`${ep.method} ${ep.path} failed`, cause));
    }
  }

  private errorFor(ep: EndpointSpec, status: number, body: unknown): Error {
    const known = decodeProblem(body);
    const declared = known ? ep.errors.find((d) => d.sig === known.type) : undefined;
    if (known && declared) {
      const data = fromWire(declared.schema, known.data ?? {});
      // #if rules
      if (known.violations !== undefined && known.violations.length > 0) {
        const init = { status: known.status || status, op: known.operation ?? ep.sig, violations: known.violations };
        return declared.create(data, init);
      }
      // #endif
      return declared.create(data, { status: known.status || status, op: known.operation ?? ep.sig });
    }
    return new VeldHttpError(status, body ?? null);
  }

  private async decode(ep: EndpointSpec, res: FetchResponse): Promise<unknown> {
    let text: string;
    try {
      text = await res.text();
    } catch (cause) {
      throw new VeldTransportError(`${ep.method} ${ep.path}: could not read the response`, cause);
    }
    let body: unknown;
    if (text.trim() !== '') {
      try {
        body = JSON.parse(text) as unknown;
      } catch (cause) {
        throw new VeldTransportError(`${ep.method} ${ep.path}: response body is not valid JSON (HTTP ${res.status})`, cause);
      }
    }
    if (res.status >= 200 && res.status < 300) {
      if (ep.success === null) return undefined;
      if (body === undefined) throw new VeldTransportError(`${ep.method} ${ep.path}: empty response body`);
      return fromWire(ep.success, body);
    }
    throw this.errorFor(ep, res.status, body);
  }
}

async function* drain(events: Queue<WsEvent>): AsyncGenerator<unknown> {
  for await (const e of events) {
    if ('err' in e) throw e.err;
    yield e.ok;
  }
}
